pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Deposit Ether via fallback to fund the contract
        address donor = makeAddr("donor");
        vm.deal(donor, depositAmount);
        vm.prank(donor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit");

        uint256 ownerBefore = address(c.owner()).balance;
        uint256 contractBefore = address(c).balance;

        // Owner attempts to withdraw
        vm.prank(c.owner());
        try c.withdraw(withdrawAmount) { } catch { }

        uint256 ownerAfter = address(c.owner()).balance;
        uint256 contractAfter = address(c).balance;

        // General invariant: owner balance change + contract balance change = 0 (conservation of Ether among the two parties)
        int256 ownerDiff = int256(ownerAfter) - int256(ownerBefore);
        int256 contractDiff = int256(contractAfter) - int256(contractBefore);
        assertTrue(ownerDiff + contractDiff == 0);
    }
}

