pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 sendAmount, uint256 withdrawAmount, bytes calldata data) public {
        vm.assume(depositAmount > 0 && sendAmount <= depositAmount && withdrawAmount <= depositAmount - sendAmount);
        vm.assume(depositAmount <= address(this).balance / 2);

        // Fund owner
        address owner = address(this);
        vm.deal(owner, depositAmount * 2);

        // Deposit via fallback
        vm.prank(owner);
        (bool ok, ) = address(c).call{value: depositAmount}("");
        assertTrue(ok);

        // sendMoney
        address payable target = payable(address(0xdead));
        vm.prank(owner);
        c.sendMoney(target, sendAmount, data);

        uint balanceBeforeWithdraw = address(c).balance;

        // Try withdraw — must not revert and must reduce balance
        vm.prank(owner);
        (bool withdrawOk, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", withdrawAmount));

        uint balanceAfterWithdraw = address(c).balance;

        // The rule: withdraw must succeed (since onlyOwner is satisfied) and contract balance must decrease by withdrawAmount.
        // In reference C, withdraw succeeds and balance decreases. In buggy, withdraw reverts, so balance unchanged.
        assertTrue(withdrawOk && balanceAfterWithdraw == balanceBeforeWithdraw - withdrawAmount);
    }
}

